pub const GenerationStats = struct {
    attempted: u64,
    accepted: u64,
    rejected_complexity: u64,
    total_tokens: u64,
    total_bytes_written: u64,

    pub fn init() GenerationStats {
        return .{
            .attempted = 0,
            .accepted = 0,
            .rejected_complexity = 0,
            .total_tokens = 0,
            .total_bytes_written = 0,
        };
    }

    pub fn acceptanceRate(self: *const GenerationStats) f32 {
        if (self.attempted == 0) return 0.0;
        return @as(f32, @floatFromInt(self.accepted)) /
               @as(f32, @floatFromInt(self.attempted));
    }
};

pub const NCADataGenerator = struct {
    allocator: Allocator,
    rng: std.rand.DefaultPrng,
    complexity_band: ComplexityBand,
    stats: GenerationStats,
    token_buf_a: [MAX_SEQUENCE_LENGTH]u16,
    token_buf_b: [MAX_SEQUENCE_LENGTH]u16,
    grid_a: NCAGrid,
    grid_b: NCAGrid,
    byte_scratch: [NCA_GRID_SIZE * NCA_GRID_SIZE * NCA_ROLLOUT_STEPS]u8,

    pub fn init(allocator: Allocator, seed: u64, band: ComplexityBand) NCADataGenerator {
        return .{
            .allocator = allocator,
            .rng = std.rand.DefaultPrng.init(seed),
            .complexity_band = band,
            .stats = GenerationStats.init(),
            .token_buf_a = undefined,
            .token_buf_b = undefined,
            .grid_a = undefined,
            .grid_b = undefined,
            .byte_scratch = undefined,
        };
    }

    fn buildByteStreamForComplexity(
        self: *NCADataGenerator,
        net: *const NCATransitionNetwork,
        initial: *const NCAGrid,
        step_count: usize,
    ) usize {
        var current: *NCAGrid = &self.grid_a;
        var next: *NCAGrid = &self.grid_b;
        current.* = initial.*;
        var byte_offset: usize = 0;
        for (0..step_count) |_| {
            var flat: [NCA_GRID_SIZE * NCA_GRID_SIZE]u8 = undefined;
            current.toBytes(&flat);
            for (flat) |b| {
                self.byte_scratch[byte_offset] = b;
                byte_offset += 1;
            }
            current.step(net, &self.rng, next);
            const tmp = current;
            current = next;
            next = tmp;
        }
        return byte_offset;
    }

    fn meetsComplexity(self: *NCADataGenerator, byte_count: usize) bool {
        const result = LZ77Estimator.estimate(self.byte_scratch[0..byte_count]);
        return self.complexity_band.contains(result.ratio);
    }

    pub fn generateSequence(self: *NCADataGenerator) NCAError!NCASequence {
        var attempt: usize = 0;
        while (attempt < MAX_GENERATION_ATTEMPTS) : (attempt += 1) {
            self.stats.attempted += 1;
            var net = NCATransitionNetwork.initRandom(&self.rng);
            var initial = NCAGrid.initRandom(&self.rng);
            const byte_count = self.buildByteStreamForComplexity(
                &net,
                &initial,
                NCA_ROLLOUT_STEPS,
            );
            if (!self.meetsComplexity(byte_count)) {
                self.stats.rejected_complexity += 1;
                continue;
            }
            var seq: NCASequence = undefined;
            seq.rollout_steps = NCA_ROLLOUT_STEPS;
            seq.alphabet_size = NCA_ALPHABET_SIZE;
            var current: *NCAGrid = &self.grid_a;
            var nxt: *NCAGrid = &self.grid_b;
            current.* = initial;
            var token_offset: usize = 0;
            for (0..NCA_ROLLOUT_STEPS) |_| {
                if (token_offset + PATCHES_PER_GRID > MAX_SEQUENCE_LENGTH) break;
                PatchTokenizer.encodeGridToTokens(current, &seq.tokens, token_offset);
                token_offset += PATCHES_PER_GRID;
                current.step(&net, &self.rng, nxt);
                const swap = current;
                current = nxt;
                nxt = swap;
            }
            seq.length = token_offset;
            const lz = LZ77Estimator.estimateTokenStream(&seq.tokens, seq.length);
            seq.complexity_ratio = lz.ratio;
            self.stats.accepted += 1;
            self.stats.total_tokens += seq.length;
            return seq;
        }
        return NCAError.GenerationFailed;
    }
};

pub const SequenceBinaryWriter = struct {
    buf: [STREAM_BUFFER_SIZE]u8,
    pos: usize,
    flushed: u64,
    file: std.fs.File,

    pub fn init(file: std.fs.File) SequenceBinaryWriter {
        return .{
            .buf = undefined,
            .pos = 0,
            .flushed = 0,
            .file = file,
        };
    }

    pub fn flush(self: *SequenceBinaryWriter) !void {
        if (self.pos == 0) return;
        try self.file.writeAll(self.buf[0..self.pos]);
        self.flushed += self.pos;
        self.pos = 0;
    }

    pub fn writeU16(self: *SequenceBinaryWriter, v: u16) !void {
        if (self.pos + 2 > STREAM_BUFFER_SIZE) try self.flush();
        self.buf[self.pos] = @intCast(v & 0xFF);
        self.buf[self.pos + 1] = @intCast(v >> 8);
        self.pos += 2;
    }

    pub fn writeSequence(self: *SequenceBinaryWriter, seq: *const NCASequence) !void {
        try self.writeU16(@intCast(seq.length));
        for (0..seq.length) |i| {
            try self.writeU16(seq.tokens[i]);
        }
        try self.writeU16(GRID_SEPARATOR_TOKEN);
    }

    pub fn deinit(self: *SequenceBinaryWriter) !void {
        try self.flush();
    }
};

pub const CheckpointHeader = struct {
    magic: u64,
    version: u32,
    sequences_generated: u64,
    total_tokens: u64,
    rng_state_lo: u64,
    rng_state_hi: u64,
    complexity_min: f32,
    complexity_max: f32,
    domain_tag: u32,

    pub fn write(self: *const CheckpointHeader, writer: anytype) !void {
        try writer.writeInt(u64, self.magic, .little);
        try writer.writeInt(u32, self.version, .little);
        try writer.writeInt(u64, self.sequences_generated, .little);
        try writer.writeInt(u64, self.total_tokens, .little);
        try writer.writeInt(u64, self.rng_state_lo, .little);
        try writer.writeInt(u64, self.rng_state_hi, .little);
        try writer.writeInt(u32, @bitCast(self.complexity_min), .little);
        try writer.writeInt(u32, @bitCast(self.complexity_max), .little);
        try writer.writeInt(u32, self.domain_tag, .little);
    }

    pub fn read(reader: anytype) !CheckpointHeader {
        var h: CheckpointHeader = undefined;
        h.magic = try reader.readInt(u64, .little);
        if (h.magic != CHECKPOINT_MAGIC) return NCAError.CheckpointCorrupt;
        h.version = try reader.readInt(u32, .little);
        if (h.version != 1) return NCAError.CheckpointVersionMismatch;
        h.sequences_generated = try reader.readInt(u64, .little);
        h.total_tokens = try reader.readInt(u64, .little);
        h.rng_state_lo = try reader.readInt(u64, .little);
        h.rng_state_hi = try reader.readInt(u64, .little);
        const cm_bits = try reader.readInt(u32, .little);
        h.complexity_min = @bitCast(cm_bits);
        const cx_bits = try reader.readInt(u32, .little);
        h.complexity_max = @bitCast(cx_bits);
        h.domain_tag = try reader.readInt(u32, .little);
        return h;
    }
};

pub const VocabAdapterEntry = struct {
    nca_token: u16,
    lm_token: u32,
    frequency: u64,
};

pub const VocabAdapter = struct {
    entries: [MAX_VOCAB_ADAPTER_MAPPINGS]VocabAdapterEntry,
    count: usize,
    nca_to_lm: [PATCH_VOCAB_SIZE]u32,
    allocator: Allocator,

    pub fn init(allocator: Allocator) VocabAdapter {
        var va: VocabAdapter = .{
            .entries = undefined,
            .count = 0,
            .nca_to_lm = undefined,
            .allocator = allocator,
        };
        for (0..PATCH_VOCAB_SIZE) |i| {
            va.nca_to_lm[i] = @intCast(i);
        }
        return va;
    }

    pub fn buildFromFrequency(self: *VocabAdapter, freq: []const u64) void {
        const valid_tokens = @min(freq.len, PATCH_VOCAB_SIZE);
        self.count = 0;
        for (0..valid_tokens) |t| {
            if (PatchTokenizer.validateToken(@intCast(t))) {
                if (self.count < MAX_VOCAB_ADAPTER_MAPPINGS) {
                    self.entries[self.count] = .{
                        .nca_token = @intCast(t),
                        .lm_token = @intCast(t),
                        .frequency = freq[t],
                    };
                    self.nca_to_lm[t] = @intCast(t);
                    self.count += 1;
                }
            }
        }
    }

    pub fn translate(self: *const VocabAdapter, nca_token: u16) u32 {
        if (nca_token >= PATCH_VOCAB_SIZE) return 0;
        return self.nca_to_lm[nca_token];
    }

    pub fn translateSequence(
        self: *const VocabAdapter,
        seq: *const NCASequence,
        out: []u32,
    ) void {
        for (0..seq.length) |i| {
            out[i] = self.translate(seq.tokens[i]);
        }
    }
};

pub const TokenFrequencyAccumulator = struct {
    counts: [PATCH_VOCAB_SIZE]u64,

    pub fn init() TokenFrequencyAccumulator {
        return .{ .counts = std.mem.zeroes([PATCH_VOCAB_SIZE]u64) };
    }

    pub fn accumulate(self: *TokenFrequencyAccumulator, seq: *const NCASequence) void {
        for (0..seq.length) |i| {
            const t = seq.tokens[i];
            if (t < PATCH_VOCAB_SIZE) {
                self.counts[t] += 1;
            }
        }
    }

    pub fn totalTokens(self: *const TokenFrequencyAccumulator) u64 {
        var total: u64 = 0;
        for (self.counts) |c| total += c;
        return total;
    }
};

pub const CurriculumScheduler = struct {
    sequences_generated: u64,
    warmup_sequences: u64,
    current_band: ComplexityBand,
    target_band: ComplexityBand,

    pub fn init(warmup: u64, target: ComplexityBand) CurriculumScheduler {
        return .{
            .sequences_generated = 0,
            .warmup_sequences = warmup,
            .current_band = .{ .min_ratio = 0.20, .max_ratio = 0.40 },
            .target_band = target,
        };
    }

    pub fn step(self: *CurriculumScheduler) ComplexityBand {
        self.sequences_generated += 1;
        if (self.sequences_generated >= self.warmup_sequences) {
            self.current_band = self.target_band;
        } else {
            const t = @as(f32, @floatFromInt(self.sequences_generated)) /
                      @as(f32, @floatFromInt(self.warmup_sequences));
            self.current_band.min_ratio = 0.20 + t * (self.target_band.min_ratio - 0.20);
            self.current_band.max_ratio = 0.40 + t * (self.target_band.max_ratio - 0.40);
        }
        return self.current_band;
    }
};

pub const PipelineConfig = struct {
    output_path: [512]u8,
    output_path_len: usize,
    target_token_count: u64,
    domain: DomainComplexityProfile,
    seed: u64,
    use_curriculum: bool,
    checkpoint_interval_sequences: u64,
    checkpoint_path: [512]u8,
    checkpoint_path_len: usize,
    verbose: bool,

    pub fn default() PipelineConfig {
        var cfg: PipelineConfig = .{
            .output_path = undefined,
            .output_path_len = 0,
            .target_token_count = 164_000_000,
            .domain = .General,
            .seed = 0xDEADBEEF_CAFEBABE,
            .use_curriculum = true,
            .checkpoint_interval_sequences = 50_000,
            .checkpoint_path = undefined,
            .checkpoint_path_len = 0,
            .verbose = false,
        };
        const op = "nca_output.bin";
        @memcpy(cfg.output_path[0..op.len], op);
        cfg.output_path_len = op.len;
        const cp = "nca_checkpoint.bin";
        @memcpy(cfg.checkpoint_path[0..cp.len], cp);
        cfg.checkpoint_path_len = cp.len;
        return cfg;
    }
};

pub const NCAPrePreTrainingPipeline = struct {
    config: PipelineConfig,
    generator: NCADataGenerator,
    freq_acc: TokenFrequencyAccumulator,
    scheduler: CurriculumScheduler,
    sequences_since_checkpoint: u64,
    vocab_adapter: VocabAdapter,

    pub fn init(allocator: Allocator, config: PipelineConfig) NCAPrePreTrainingPipeline {
        const band = config.domain.complexityBand();
        return .{
            .config = config,
            .generator = NCADataGenerator.init(allocator, config.seed, band),
            .freq_acc = TokenFrequencyAccumulator.init(),
            .scheduler = CurriculumScheduler.init(CURRICULUM_WARMUP_SEQUENCES, band),
            .sequences_since_checkpoint = 0,
            .vocab_adapter = VocabAdapter.init(allocator),
        };
    }

    pub fn saveCheckpoint(self: *NCAPrePreTrainingPipeline) !void {
        const path = self.config.checkpoint_path[0..self.config.checkpoint_path_len];
        const file = try std.fs.cwd().createFile(path, .{ .truncate = true });
        defer file.close();
        var bw = std.io.bufferedWriter(file.writer());
        const writer = bw.writer();
        const rng_state = self.generator.rng.s;
        const hdr = CheckpointHeader{
            .magic = CHECKPOINT_MAGIC,
            .version = 1,
            .sequences_generated = self.generator.stats.accepted,
            .total_tokens = self.generator.stats.total_tokens,
            .rng_state_lo = rng_state[0],
            .rng_state_hi = rng_state[1],
            .complexity_min = self.generator.complexity_band.min_ratio,
            .complexity_max = self.generator.complexity_band.max_ratio,
            .domain_tag = @intFromEnum(self.config.domain),
        };
        try hdr.write(writer);
        for (self.freq_acc.counts) |c| {
            try writer.writeInt(u64, c, .little);
        }
        try bw.flush();
    }

    pub fn run(self: *NCAPrePreTrainingPipeline) !void {
        const out_path = self.config.output_path[0..self.config.output_path_len];
        const out_file = try std.fs.cwd().createFile(out_path, .{ .truncate = true });
        defer out_file.close();
        var writer = SequenceBinaryWriter.init(out_file);

        const stderr = std.io.getStdErr().writer();
        var last_log_tokens: u64 = 0;
        const LOG_INTERVAL: u64 = 1_000_000;

        while (self.generator.stats.total_tokens < self.config.target_token_count) {
            if (self.config.use_curriculum) {
                const new_band = self.scheduler.step();
                self.generator.complexity_band = new_band;
            }

            const seq = self.generator.generateSequence() catch |err| switch (err) {
                NCAError.GenerationFailed => continue,
                else => return err,
            };

            try writer.writeSequence(&seq);
            self.freq_acc.accumulate(&seq);
            self.sequences_since_checkpoint += 1;

            if (self.sequences_since_checkpoint >= self.config.checkpoint_interval_sequences) {
                try self.saveCheckpoint();
                self.sequences_since_checkpoint = 0;
            }

            if (self.config.verbose and
                self.generator.stats.total_tokens - last_log_tokens >= LOG_INTERVAL)
            {
                last_log_tokens = self.generator.stats.total_tokens;
                try stderr.print(
                    "[NCA] tokens={d} sequences={d} acceptance={d:.3} complexity_band=[{d:.2},{d:.2}]\n",
                    .{
                        self.generator.stats.total_tokens,
                        self.generator.stats.accepted,
                        self.generator.stats.acceptanceRate(),
                        self.generator.complexity_band.min_ratio,
                        self.generator.complexity_band.max_ratio,
                    },
                );
            }
        }

        self.vocab_adapter.buildFromFrequency(&self.freq_acc.counts);
        try writer.deinit();
        try self.saveCheckpoint();

        if (self.config.verbose) {
            try stderr.print(
                "[NCA] done. tokens={d} acceptance_rate={d:.3} total_attempted={d}\n",
                .{
                    self.generator.stats.total_tokens,
                    self.generator.stats.acceptanceRate(),
                    self.generator.stats.attempted,
                },
            );
        }
    }
};

fn parseArgs(args: [][]u8, config: *PipelineConfig) NCAError!void {
    var i: usize = 1;
    while (i < args.len) : (i += 1) {
        const arg = args[i];
        if (mem.eql(u8, arg, "--domain") and i + 1 < args.len) {
            i += 1;
            config.domain = try DomainComplexityProfile.fromString(args[i]);
        } else if (mem.eql(u8, arg, "--tokens") and i + 1 < args.len) {
            i += 1;
            config.target_token_count = std.fmt.parseInt(u64, args[i], 10) catch
                return NCAError.InvalidArguments;
        } else if (mem.eql(u8, arg, "--seed") and i + 1 < args.len) {
            i += 1;
            config.seed = std.fmt.parseInt(u64, args[i], 16) catch
                return NCAError.SeedRequired;
        } else if (mem.eql(u8, arg, "--output") and i + 1 < args.len) {
            i += 1;
            const p = args[i];
            if (p.len >= 512) return NCAError.OutputPathTooLong;
            @memcpy(config.output_path[0..p.len], p);
            config.output_path_len = p.len;
        } else if (mem.eql(u8, arg, "--checkpoint") and i + 1 < args.len) {
            i += 1;
            const p = args[i];
            if (p.len >= 512) return NCAError.OutputPathTooLong;
            @memcpy(config.checkpoint_path[0..p.len], p);
            config.checkpoint_path_len = p.len;
        } else if (mem.eql(u8, arg, "--no-curriculum")) {
            config.use_curriculum = false;
        } else if (mem.eql(u8, arg, "--verbose")) {
            config.verbose = true;
        }
    }
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var args = try std.process.argsAlloc(allocator);
    defer std.process.argsFree(allocator, args);

    var config = PipelineConfig.default();
    parseArgs(args, &config) catch |err| {
        const stderr = std.io.getStdErr().writer();
        try stderr.print("arg parse error: {}\n", .{err});
        std.process.exit(1);
    };

    var pipeline = NCAPrePreTrainingPipeline.init(allocator, config);
    try pipeline.run();
}

